/**
 * Milestone M4 Expansion — Part 2 (90 Curated Academic TOEIC X-Ray Items)
 * Topics:
 *   3. LC_P1_P2_DIRECT_INDIRECT   (+45 items: EXP2026_LC_P12_Q001..Q045) -> 0 + 45 = 45
 *   4. LC_P3_P4_CONVERSATION_TALK (+45 items: EXP2026_LC_P34_Q001..Q045) -> 0 + 45 = 45
 */

import { buildQuestionFromSpec } from "./m2_items_part1.mjs";

const KEYS = ["A", "B", "C", "D"];

function makeM4ListeningGenerator({
  topicId,
  topicNameVi,
  idPrefix,
  part = 2,
  skillCategory = "LISTENING_COMPREHENSION",
  defaultBand = 600,
  defaultTime = 15,
  commonTrapVi,
  errCode = "ERR_COMPREHENSION_TRAP",
  errNameVi = "Bẫy đồng âm / lặp từ khóa (Homophone / Verbatim Trap) hoặc sai mục đích giao tiếp",
  scenarios,
}) {
  return function generate() {
    const allIds = scenarios.map((_, idx) => `${idPrefix}_Q${String(idx + 1).padStart(3, "0")}`);

    return scenarios.map((sc, idx) => {
      const qNum = idx + 1;
      const id = allIds[idx];
      const diff = idx < 15 ? 1 : idx < 30 ? 2 : 3;
      const band = sc.band || (diff === 1 ? 450 : diff === 2 ? 600 : 750);

      const correctIdx = idx % 4;
      const correctKey = KEYS[correctIdx];
      const options = {};
      let dPtr = 0;

      for (let kIdx = 0; kIdx < 4; kIdx++) {
        const k = KEYS[kIdx];
        if (kIdx === correctIdx) {
          options[k] = {
            text: sc.corr,
            role: sc.role,
            errCode: null,
            errNameVi: null,
            whyWrongVi: "",
          };
        } else {
          const dItem = sc.dist[dPtr++];
          const dText = typeof dItem === "object" ? dItem.t : dItem;
          const dRole = typeof dItem === "object" ? dItem.r : "Listening Distractor (Sound-alike / Wrong WH-focus)";
          const dWhy =
            typeof dItem === "object" && dItem.w
              ? dItem.w
              : `Bẫy nghe hiểu TOEIC: "${dText}" là phương án nhiễu (bẫy phát âm tương tự / lặp từ / sai trọng tâm câu hỏi) không khớp với "${sc.la} ... ${sc.ra}".`;
          options[k] = {
            text: dText,
            role: dRole,
            errCode: sc.errCode || errCode,
            errNameVi: sc.errNameVi || errNameVi,
            whyWrongVi: dWhy,
          };
        }
      }

      const twin1 = allIds[(idx + 1) % allIds.length];
      const twin2 = allIds[(idx + 2) % allIds.length];

      return buildQuestionFromSpec({
        id,
        number: (part === 2 ? 7 : 32) + (idx % 45),
        part: sc.part || part,
        topicId,
        topicNameVi,
        skillCategory,
        difficultyLevel: diff,
        targetBand: band,
        recommendedTime: defaultTime,
        microFormulaVi: sc.rule,
        commonTrapVi: sc.trap || commonTrapVi,
        leftContext: sc.l,
        rightContext: sc.r,
        leftAnchor: sc.la,
        rightAnchor: sc.ra,
        requiredRole: sc.role,
        options,
        correctKey,
        explanationVi: `Chốt chặn Nghe hiểu X-Ray: Tín hiệu "${sc.la} ... ${sc.ra}" đòi hỏi ${sc.role} theo quy tắc "${sc.rule}". Đáp án (${correctKey}) "${sc.corr}" là chính xác nhất.`,
        vocab: [{ word: sc.v[0], pos: sc.v[1], meaning_vi: sc.v[2] }],
        collocation: sc.c,
        similarIds: [twin1, twin2],
      });
    });
  };
}

